+func TestSearchWorkspaceTasks_UpdatedAtPresent(t *testing.T) {
+	ws := makeTestWorkspace()
+	status := "in_progress"
+	updatedAt := time.Date(2026, 5, 29, 11, 59, 28, 0, time.UTC)
+	task := database2.WorkspaceTask{
+		FeatureName: "feature-1",
+		TaskName:    "T1",
+		Title:       "Task One",
+		Status:      &status,
+	}
+	_ = task.ID.Scan("88888888-8888-8888-8888-888888888888")
+	_ = task.TaskID.Scan(handlerTestTaskRowID)
+	_ = task.FeatureID.Scan(handlerTestFeatureRowID)
+	_ = task.WorkspaceID.Scan(handlerTestWSID)
+	_ = task.UpdatedAt.Scan(updatedAt)
+
+	db := &fakeDB{
+		workspaces: []database2.Workspace{ws},
+		tasks:      []database2.WorkspaceTask{task},
+	}
+	r := newTestRouter(db, &fakeAdapter{})
+
+	w := httptest.NewRecorder()
+	req, _ := http.NewRequestWithContext(context.Background(), http.MethodGet,
+		"/api/workspaces/"+handlerTestWSID+"/tasks?status=in_progress&sort=task_id_asc&page=1&limit=50", nil)
+	r.ServeHTTP(w, req)
+
+	if w.Code != http.StatusOK {
+		t.Fatalf("expected 200, got %d: %s", w.Code, w.Body.String())
+	}
+
+	paged := decodeAPIData[domain.PagedTasks](t, w.Body.Bytes())
+	if len(paged.Items) != 1 {
+		t.Fatalf("expected 1 task item, got %d", len(paged.Items))
+	}
+	item := paged.Items[0]
+	if item.UpdatedAt.IsZero() {
+		t.Error("expected updated_at to be non-zero on task item")
+	}
+	if !item.UpdatedAt.Equal(updatedAt) {
+		t.Errorf("expected updated_at %v, got %v", updatedAt, item.UpdatedAt)
+	}
+}
+
+func TestSearchWorkspaceTasks_AllItemsHaveUpdatedAt(t *testing.T) {
+	ws := makeTestWorkspace()
+	statuses := []string{"blocked", "in_progress", "reviewing", "in_review", "ready"}
+	tasks := make([]database2.WorkspaceTask, 0, len(statuses))
+	for i, st := range statuses {
+		s := st
+		updatedAt := time.Now().Add(-time.Duration(i) * time.Hour)
+		task := database2.WorkspaceTask{
+			FeatureName: "feature-1",
+			TaskName:    "T" + string(rune('1'+i)),
+			Title:       "Task " + st,
+			Status:      &s,
+		}
+		_ = task.ID.Scan("8888888" + string(rune('0'+i)) + "-8888-8888-8888-888888888888")
+		_ = task.TaskID.Scan("9999999" + string(rune('0'+i)) + "-9999-9999-9999-999999999999")
+		_ = task.FeatureID.Scan(handlerTestFeatureRowID)
+		_ = task.WorkspaceID.Scan(handlerTestWSID)
+		_ = task.UpdatedAt.Scan(updatedAt)
+		tasks = append(tasks, task)
+	}
+
+	db := &fakeDB{
+		workspaces: []database2.Workspace{ws},
+		tasks:      tasks,
+	}
+	r := newTestRouter(db, &fakeAdapter{})
+
+	w := httptest.NewRecorder()
+	req, _ := http.NewRequestWithContext(context.Background(), http.MethodGet,
+		"/api/workspaces/"+handlerTestWSID+"/tasks?status=blocked,in_progress,reviewing,in_review,ready&sort=task_id_asc&page=1&limit=50", nil)
+	r.ServeHTTP(w, req)
+
+	if w.Code != http.StatusOK {
+		t.Fatalf("expected 200, got %d: %s", w.Code, w.Body.String())
+	}
+
+	paged := decodeAPIData[domain.PagedTasks](t, w.Body.Bytes())
+	for i, item := range paged.Items {
+		if item.UpdatedAt.IsZero() {
+			t.Errorf("task item[%d] (%s) has zero updated_at", i, item.TaskName)
+		}
+	}
+}
+
